import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"x.com 投稿用下書き — 日本語 thread (v1.4 polyglot 完成 voice)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.4/x-thread-ja.md","filePath":"announcements/v1.4/x-thread-ja.md"}'),d={name:"announcements/v1.4/x-thread-ja.md"};function i(c,e,l,n,s,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="x-com-投稿用下書き-—-日本語-thread-v1-4-polyglot-完成-voice" tabindex="-1">x.com 投稿用下書き — 日本語 thread (v1.4 polyglot 完成 voice) <a class="header-anchor" href="#x-com-投稿用下書き-—-日本語-thread-v1-4-polyglot-完成-voice" aria-label="Permalink to &quot;x.com 投稿用下書き — 日本語 thread (v1.4 polyglot 完成 voice)&quot;">​</a></h1><blockquote><p>投稿先 ... <a href="https://x.com/cardene777" target="_blank" rel="noreferrer">@cardene777</a> Voice ... 本人名義 / 個人 dev 視点 / 「v0.5 公約回収」 maker トーン 動画 ... <code>assets/kiwa-promo-ja.mp4</code> (再利用) を 1 ツイート目に添付 想定 ... 1 ツイート 140 字以内 全 8 ツイート、 番号 [1/8] 付き</p></blockquote><hr><h2 id="_1-8-動画添付" tabindex="-1">[1/8] (動画添付) <a class="header-anchor" href="#_1-8-動画添付" aria-label="Permalink to &quot;[1/8] (動画添付)&quot;">​</a></h2><p>polyglot test toolchain 「kiwa」 v1.4 (6/6 resolved) が land しました。</p><p>Rust + Go が加わって <strong>5 言語 (TS / Python / Solidity + Rust + Go) polyglot 完成版</strong>。 v0.5 で「Rust / Go は構想中」 と書いた公約をようやく回収。</p><p><a href="https://github.com/cardene777/kiwa" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa</a></p><p>#OSS #testing</p><hr><h2 id="_2-8" tabindex="-1">[2/8] <a class="header-anchor" href="#_2-8" aria-label="Permalink to &quot;[2/8]&quot;">​</a></h2><p>v1.4 で増えたもの。</p><ul><li>対応言語 ... 3 → 5 (+ Rust + Go)</li><li>skill ... 25 → 27 (+ kiwa-rust + kiwa-go)</li><li>Layer 1 spec layer ... 9 → 13 (+ 4 polyglot layer)</li><li>他言語 package ... PyPI 1 → PyPI + crates.io + pkg.go.dev = 3</li></ul><hr><h2 id="_3-8" tabindex="-1">[3/8] <a class="header-anchor" href="#_3-8" aria-label="Permalink to &quot;[3/8]&quot;">​</a></h2><p>Rust (kiwa-test-rs v0.1) ...</p><ul><li><code>cargo test</code> adapter (unit、 <code>setup_env</code> + <code>assert_kiwa_eq!</code> / <code>assert_kiwa_close!</code>)</li><li><code>hyper</code> mock_server (integration、 <code>RecordedRequest</code> で受信 capture)</li><li><code>integration</code> feature default ON、 unit-only は opt-out 可</li></ul><hr><h2 id="_4-8" tabindex="-1">[4/8] <a class="header-anchor" href="#_4-8" aria-label="Permalink to &quot;[4/8]&quot;">​</a></h2><p>Go (kiwa-test-go v0.1) ...</p><ul><li><code>testing.T</code> adapter (<code>SetupUnitEnv</code> + <code>t.Cleanup</code> 自動 stop)</li><li><code>httptest.Server</code> wrap (integration、 stdlib zero-dep)</li><li><code>testing.TB</code> accept で <code>T</code> / <code>B</code> / <code>F</code> 全対応、 race clean</li></ul><hr><h2 id="_5-8" tabindex="-1">[5/8] <a class="header-anchor" href="#_5-8" aria-label="Permalink to &quot;[5/8]&quot;">​</a></h2><p><code>/kiwa-design</code> に 4 layer 追加 (<code>rust-unit</code> / <code>rust-integration</code> / <code>go-unit</code> / <code>go-integration</code>)。</p><p>1 機能を 5 言語で同時 spec → <code>/kiwa-rust</code> + <code>/kiwa-go</code> で並列 test 生成。</p><hr><h2 id="_6-8" tabindex="-1">[6/8] <a class="header-anchor" href="#_6-8" aria-label="Permalink to &quot;[6/8]&quot;">​</a></h2><p>「test stack 散乱」 問題は runner だけでなく <strong>言語違い</strong> にもあります。</p><p>dApp 開発でも Solidity / TS / Python / Rust crypto / Go gateway は普通に出てきて、 これを 1 spec から並列展開できるのが kiwa polyglot の意義です。</p><hr><h2 id="_7-8" tabindex="-1">[7/8] <a class="header-anchor" href="#_7-8" aria-label="Permalink to &quot;[7/8]&quot;">​</a></h2><p>統計 ...</p><table tabindex="0"><thead><tr><th>軸</th><th>v1.3</th><th>v1.4</th></tr></thead><tbody><tr><td>対応言語</td><td>3</td><td><strong>5</strong></td></tr><tr><td>skill</td><td>25</td><td>27</td></tr><tr><td>Layer 1 spec layer</td><td>9</td><td>13</td></tr></tbody></table><p>5 言語 polyglot の現在地、 dApp + web + lib + サービスを 1 spec で扱える状態に到達。</p><hr><h2 id="_8-8" tabindex="-1">[8/8] <a class="header-anchor" href="#_8-8" aria-label="Permalink to &quot;[8/8]&quot;">​</a></h2><p>v1.5 候補は Rust / Go web framework adapter (axum / actix / Gin / Echo) + 新 layer (auth / job queue / cache)。</p><p>要望は GitHub Discussions で集めます。</p><p><a href="https://github.com/cardene777/kiwa/discussions" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/discussions</a></p><p>#testing #rust #golang</p>',39)])])}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
